SET default_transaction_read_only = on;
SET TIME ZONE 'UTC';
\copy (SELECT t.id, t.ticker, t.alert_date, t.account_mode, t.signal_type, t.entry_attempt, t.status, t.regime, t.ep_score, t.gap_pct, t.orb_high, t.orb_low, t.atr_14, t.entry_price, t.entry_shares, t.stop_price, t.hard_stop, t.risk_dollars, t.risk_dollars_actual, t.total_pnl, t.hold_days, t.partial_taken, t.breakeven_active, t.pnl_attribution, t.exit_rule, t.highest_price_seen, t.lowest_price_seen, t.exits::text AS exits, t.filled_at, t.closed_at, (t.filled_at AT TIME ZONE 'America/New_York')::date AS fill_day_et, now() AS captured_at FROM mi_live_trades t WHERE t.account_mode = 'live' AND t.signal_type = 'magna53' AND t.filled_at IS NOT NULL AND (t.filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16' ORDER BY t.filled_at, t.id) TO STDOUT WITH CSV HEADER

SET default_transaction_read_only = on;
SET TIME ZONE 'UTC';
\copy (SELECT c.id, c.trade_id, c.ticker, c.account_mode, c.signal_type, c.entry_attempt, c.alert_date, c.fill_day, c.arm, c.arm_kind, c.stop_rule, c.harvest_rule, c.trail_rule, c.entry_rule, c.entry_minute, c.entry_price, c.orb_high, c.orb_low, c.live_stop, c.target_price, c.target_r, c.breakeven_arm_r, c.adr20_pct, c.adr20_n, c.adr_dollar, c.stop_price, c.risk_per_share, c.stop_width_pct, c.stop_width_adr, c.outcome, c.final_reason, c.realized_r, c.realized_pct, c.pnl_adr, c.mark_r, c.partial_fired, c.gap_through, c.exit_session, c.sessions_walked, c.day0_bar_count, c.exits::text AS exits, c.pnl_attribution, c.regime, c.exit_era, c.exit_rules::text AS exit_rules, c.admission_era, c.rubric_version, c.score_tier, c.ep_score, c.judge_grade, c.judge_tier, c.grade_engine_authority, c.setup_class, c.baseline_floor_tier, c.alert_source, c.fill_vs_trigger_pct, c.fill_slippage_dollars, c.real_risk_dollars, c.risk_budget_dollars, c.real_risk_vs_budget, c.real_risk_vs_trigger_risk, c.sizing_risk_pct, c.sizing_regime_mult, c.risk_frac_capped, c.cap_binding, c.realized_r_capped, c.settle_version, c.settled_session, c.recorded_at FROM mi_live_fill_counterfactuals c WHERE c.account_mode = 'live' AND c.signal_type = 'magna53' ORDER BY c.trade_id, c.arm) TO STDOUT WITH CSV HEADER

SET default_transaction_read_only = on;
SET TIME ZONE 'UTC';
\copy (SELECT s.id, s.ticker, s.alert_date, s.bar_size_minutes, s.signal_type, s.shape_tag, s.score_tier, s.orb_high, s.orb_low, s.atr_14, s.trigger_minute_et, s.entry_price, s.stop_price, s.hard_stop, s.risk_dollars, s.entry_shares, s.status, s.skip_reason, s.exits::text AS exits, s.remaining_shares, s.partial_taken, s.breakeven_active, s.total_pnl, s.hold_days, s.quarantined, s.replayed_at, s.created_at, s.closed_at FROM mi_orb_shadow_trades s WHERE s.bar_size_minutes = 5 AND s.status = 'closed' AND NOT s.quarantined AND s.signal_type = 'magna53' AND s.alert_date >= DATE '2026-08-17' ORDER BY s.alert_date, s.ticker) TO STDOUT WITH CSV HEADER

SET default_transaction_read_only = on;
SET TIME ZONE 'UTC';
\copy (SELECT s.id, s.ticker, s.alert_date, s.bar_size_minutes, s.signal_type, s.entry_price, s.hard_stop, s.status, s.quarantined, s.replayed_at, s.created_at FROM mi_orb_shadow_trades s WHERE s.bar_size_minutes = 5 AND s.status = 'open' AND NOT s.quarantined AND s.signal_type = 'magna53' AND s.alert_date >= DATE '2026-08-17' ORDER BY s.alert_date, s.ticker) TO STDOUT WITH CSV HEADER
